            make(79, "An-Nazi'at", 2, "وَالنَّاشِطَاتِ نَشْطًا", "وَ<hamzat_wasl>ال</hamzat_wasl><ghunnah>نَّاشِطَاتِ</ghunnah> نَشْطًا", "Wan-nashitati nashta", "And [by] those who remove with ease", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH)),
            make(79, "An-Nazi'at", 3, "وَالسَّابِحَاتِ سَبْحًا", "وَ<hamzat_wasl>ال</hamzat_wasl>سَّابِحَاتِ <qalqalah>سَبْ</qalqalah>حًا", "Was-sabihati sabha", "And [by] those who glide [as if] swimming", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.QALQALAH)),
            make(79, "An-Nazi'at", 4, "فَالسَّابِقَاتِ سَبْقًا", "فَ<hamzat_wasl>ال</hamzat_wasl>سَّابِقَاتِ <qalqalah>سَبْ</qalqalah><qalqalah>قً</qalqalah>ا", "Fas-sabiqati sabqa", "And those who race each other in a race", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.QALQALAH)),
