            make(79, "An-Nazi'at", 6, "يَوْمَ تَرْجُفُ الرَّاجِفَةُ", "يَوْمَ تَرْجُفُ <hamzat_wasl>ال</hamzat_wasl>رَّاجِفَةُ", "Yawma tarjufur-rajifah", "On the Day the quaking [horn blast] will quake,", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(79, "An-Nazi'at", 7, "تَتْبَعُهَا الرَّادِفَةُ", "تَتْبَعُهَا <hamzat_wasl>ال</hamzat_wasl>رَّادِفَةُ", "Tatba'uhar-radifah", "There will follow it the subsequent [one].", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(79, "An-Nazi'at", 8, "قُلُوبٌ يَوْمَئِذٍ وَاجِفَةٌ", "<tafkhim>قُلُوبٌ</tafkhim> <idgham>يَوْمَئِذٍ</idgham> <idgham>وَاجِفَةٌ</idgham>", "Qulubuy yawma'idhiw wajifah", "Hearts, that Day, will tremble,", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.IDGHAM)),
            make(79, "An-Nazi'at", 9, "أَبْصَارُهَا خَاشِعَةٌ", "أَ<qalqalah>بْ</qalqalah><tafkhim>صَارُهَا</tafkhim> خَاشِعَةٌ", "Absaruha khashi'ah", "Their eyes humbled.", listOf(TajweedRuleType.QALQALAH, TajweedRuleType.TAFKHIM)),
            make(79, "An-Nazi'at", 10, "يَقُولُونَ أَإِنَّا لَمَرْدُودُونَ فِي الْحَافِرَةِ", "يَقُولُونَ <madd>أَإِنَّا</madd> لَمَرْدُودُونَ فِي <hamzat_wasl>الْ</hamzat_wasl>حَافِرَةِ", "Yaquluna a'inna lamarduduna fil-hafirah", "They are saying, 'Will we indeed be returned to [our] former state [of life]?'", listOf(TajweedRuleType.MADD, TajweedRuleType.HAMZAT_WASL)),
            make(79, "An-Nazi'at", 11, "أَإِذَا كُنَّا عِظَامًا نَّخِرَةً", "أَإِذَا <ghunnah>كُنَّا</ghunnah> عِ<tafkhim>ظَامًا</tafkhim> <idgham>نَّخِرَةً</idgham>", "A-idha kunna 'izaman nakhirah", "'Even if we should be decayed bones?'", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.TAFKHIM, TajweedRuleType.IDGHAM)),
            make(79, "An-Nazi'at", 12, "قَالُوا تِلْكَ إِذًا كَرَّةٌ خَاسِرَةٌ", "<tafkhim>قَالُوا</tafkhim> تِلْكَ إِذًا كَرَّةٌ خَاسِرَةٌ", "Qalu tilka idhan karratun khasirah", "They say, 'That, then, would be a losing return.'", listOf(TajweedRuleType.TAFKHIM)),
            make(79, "An-Nazi'at", 13, "فَإِنَّمَا هِيَ زَجْرَةٌ وَاحِدَةٌ", "فَ<ghunnah>إِنَّمَا</ghunnah> هِيَ <qalqalah>زَجْ</qalqalah>رَةٌ <idgham>وَاحِدَةٌ</idgham>", "Fa-innama hiya zajratuw wahidah", "Indeed, it will be but one shout,", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.QALQALAH, TajweedRuleType.IDGHAM)),
            make(79, "An-Nazi'at", 14, "فَإِذَا هُم بِالسَّاهِرَةِ", "فَإِذَا هُم <ikhfa>بِ</ikhfa><hamzat_wasl>ال</hamzat_wasl>سَّاهِرَةِ", "Fa-idha hum bis-sahirah", "And suddenly they will be [alert] upon the earth's surface.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL)),
            make(79, "An-Nazi'at", 15, "هَلْ أَتَاكَ حَدِيثُ مُوسَىٰ", "هَلْ أَتَاكَ حَدِيثُ مُوسَىٰ", "Hal ataka hadithu Musa", "Has there reached you the story of Moses?", emptyList()),
            make(79, "An-Nazi'at", 16, "إِذْ نَادَاهُ رَبُّهُ بِالْوَادِ الْمُقَدَّسِ طُوًى", "إِذْ نَادَاهُ رَبُّهُ بِ<hamzat_wasl>الْ</hamzat_wasl>وَادِ <hamzat_wasl>الْ</hamzat_wasl>مُ<qalqalah>قَدَّسِ</qalqalah> <tafkhim>طُوًى</tafkhim>", "Idh nadahu rabbuhu bil-wadil-muqaddasi tuwa", "When his Lord called to him in the sacred valley of Tuwa,", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(79, "An-Nazi'at", 17, "اذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُ طَغَىٰ", "<hamzat_wasl>ا</hamzat_wasl>ذْهَ<qalqalah>بْ</qalqalah> إِلَىٰ فِرْعَوْنَ <ghunnah>إِنَّهُ</ghunnah> <tafkhim>طَغَىٰ</tafkhim>", "Idh-hab ila fir'awna innahu tagha", "'Go to Pharaoh. Indeed, he has transgressed.'", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.QALQALAH, TajweedRuleType.GHUNNAH, TajweedRuleType.TAFKHIM)),
            make(79, "An-Nazi'at", 18, "فَقُلْ هَل لَّكَ إِلَىٰ أَن تَزَكَّىٰ", "فَ<qalqalah>قُلْ</qalqalah> هَل <idgham>لَّكَ</idgham> إِلَىٰ <madd>أَن</madd> <ikhfa>تَزَكَّىٰ</ikhfa>", "Faqul hal laka ila an tazakka", "And say to him, 'Would you [be willing to] purify yourself'", listOf(TajweedRuleType.QALQALAH, TajweedRuleType.IDGHAM, TajweedRuleType.GHUNNAH)),
            make(79, "An-Nazi'at", 19, "وَأَهْدِيَكَ إِلَىٰ رَبِّكَ فَتَخْشَىٰ", "وَأَهْدِيَكَ إِلَىٰ رَبِّكَ فَتَخْشَىٰ", "Wa ahdiyaka ila rabbika fatakhsha", "'And let me guide you to your Lord so you would fear [Him]?'", emptyList()),
            make(79, "An-Nazi'at", 20, "فَأَرَاهُ الْآيَةَ الْكُبْرَىٰ", "فَأَرَاهُ <hamzat_wasl>الْ</hamzat_wasl><madd>آيَةَ</madd> <hamzat_wasl>الْ</hamzat_wasl>كُ<qalqalah>بْ</qalqalah>رَىٰ", "Fa-arahul-ayatal-kubra", "And he showed him the greatest sign,", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD, TajweedRuleType.QALQALAH)),
            make(79, "An-Nazi'at", 21, "فَكَذَّبَ وَعَصَىٰ", "فَكَذَّبَ وَ<tafkhim>عَصَىٰ</tafkhim>", "Fakadhdhaba wa 'asa", "But Pharaoh denied and disobeyed.", listOf(TajweedRuleType.TAFKHIM)),
            make(79, "An-Nazi'at", 22, "ثُمَّ أَدْبَرَ يَسْعَىٰ", "<ghunnah>ثُمَّ</ghunnah> <madd>أَ</madd><qalqalah>دْ</qalqalah>بَرَ يَسْعَىٰ", "Thumma adbara yas'a", "Then he turned his back, striving.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.QALQALAH)),
            make(79, "An-Nazi'at", 23, "فَحَشَرَ فَنَادَىٰ", "فَحَشَرَ فَنَادَىٰ", "Fahashara fanada", "And he gathered [his people] and called out", emptyList()),
            make(79, "An-Nazi'at", 24, "فَقَالَ أَنَا رَبُّكُمُ الْأَعْلَىٰ", "فَ<tafkhim>قَالَ</tafkhim> أَنَا رَبُّكُمُ <hamzat_wasl>الْ</hamzat_wasl>أَعْلَىٰ", "Faqala ana rabbukumul-a'la", "And said, 'I am your most exalted lord.'", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.HAMZAT_WASL)),
            make(79, "An-Nazi'at", 25, "فَأَخَذَهُ اللَّهُ نَكَالَ الْآخِرَةِ وَالْأُولَىٰ", "فَأَخَذَهُ <hamzat_wasl>ال</hamzat_wasl><tafkhim>لَّهُ</tafkhim> نَكَالَ <hamzat_wasl>الْ</hamzat_wasl><madd>آخِرَةِ</madd> وَ<hamzat_wasl>الْ</hamzat_wasl>أُولَىٰ", "Fa-akhadhahul-lahu nakalal-akhirati wal-ula", "So Allah seized him in exemplary punishment for the last and the first [transgression].", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM, TajweedRuleType.MADD)),
            make(79, "An-Nazi'at", 26, "إِنَّ فِي ذَٰلِكَ لَعِبْرَةً لِّمَن يَخْشَىٰ", "<ghunnah>إِنَّ</ghunnah> فِي ذَٰلِكَ لَعِ<qalqalah>بْ</qalqalah>رَةً <idgham>لِّمَن</idgham> <idgham>يَخْشَىٰ</idgham>", "Inna fi dhalika la'ibratal limay yakhsha", "Indeed in that is a warning for whoever would fear [Allah].", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.QALQALAH, TajweedRuleType.IDGHAM)),
            make(79, "An-Nazi'at", 27, "أَأَنتُمْ أَشَدُّ خَلْقًا أَمِ السَّمَاءُ ۚ بَنَاهَا", "أَ<ikhfa>أَنتُمْ</ikhfa> أَشَدُّ خَلْ<qalqalah>قً</qalqalah>ا أَمِ <hamzat_wasl>ال</hamzat_wasl><madd>سَّمَاءُ</madd> ۚ بَنَاهَا", "A-antum ashaddu khalqan amis-sama'u banaha", "Are you a more difficult creation or is the heaven? Allah constructed it.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.QALQALAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD)),
            make(79, "An-Nazi'at", 28, "رَفَعَ سَمْكَهَا فَسَوَّاهَا", "رَفَعَ سَمْكَهَا فَسَوَّاهَا", "Rafa'a samkaha fasawwaha", "He raised its ceiling and proportioned it.", emptyList()),
            make(79, "An-Nazi'at", 29, "وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَاهَا", "وَأَ<tafkhim>غْطَشَ</tafkhim> لَيْلَهَا وَأَخْرَجَ <tafkhim>ضُحَاهَا</tafkhim>", "Wa aghtasha laylaha wa akhraja duhaha", "And He darkened its night and extracted its brightness.", listOf(TajweedRuleType.TAFKHIM)),
            make(79, "An-Nazi'at", 30, "وَالْأَرْضَ بَعْدَ ذَٰلِكَ دَحَاهَا", "وَ<hamzat_wasl>الْ</hamzat_wasl>أَرْضَ بَعْدَ ذَٰلِكَ دَحَاهَا", "Wal-arda ba'da dhalika dahaha", "And after that He spread the earth.", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(79, "An-Nazi'at", 31, "أَخْرَجَ مِنْهَا مَاءَهَا وَمَرْعَاهَا", "أَخْرَجَ مِنْهَا <madd>مَاءَهَا</madd> وَمَرْعَاهَا", "Akhraja minha ma'aha wa mar'aha", "He extracted from it its water and its pasture,", listOf(TajweedRuleType.MADD)),
            make(79, "An-Nazi'at", 32, "وَالْجِبَالَ أَرْسَاهَا", "وَ<hamzat_wasl>الْ</hamzat_wasl>جِبَالَ أَرْسَاهَا", "Wal-jibala arsaha", "And the mountains He set firmly", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(79, "An-Nazi'at", 33, "مَتَاعًا لَّكُمْ وَلِأَنْعَامِكُمْ", "مَتَاعًا <idgham>لَّكُمْ</idgham> وَلِأَنْعَامِكُمْ", "Mata'al lakum wa li-an'amikum", "As provision for you and your grazing livestock.", listOf(TajweedRuleType.IDGHAM)),
            make(79, "An-Nazi'at", 34, "فَإِذَا جَاءَتِ الطَّامَّةُ الْكُبْرَىٰ", "فَإِذَا <madd>جَاءَتِ</madd> <hamzat_wasl>ال</hamzat_wasl><madd>طَّامَّةُ</madd> <hamzat_wasl>الْ</hamzat_wasl>كُ<qalqalah>بْ</qalqalah>رَىٰ", "Fa-idha ja'atit-tammatul-kubra", "But when there comes the greatest Overwhelming Calamity -", listOf(TajweedRuleType.MADD, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.QALQALAH)),
            make(79, "An-Nazi'at", 35, "يَوْمَ يَتَذَكَّرُ الْإِنسَانُ مَا سَعَىٰ", "يَوْمَ يَتَذَكَّرُ <hamzat_wasl>الْ</hamzat_wasl>إِ<ikhfa>نسَانُ</ikhfa> مَا سَعَىٰ", "Yawma yatadhakkarul-insanu ma sa'a", "The Day when man will remember that for which he strove,", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH)),
            make(79, "An-Nazi'at", 36, "وَبُرِّزَتِ الْجَحِيمُ لِمَن يَرَىٰ", "وَبُرِّزَتِ <hamzat_wasl>الْ</hamzat_wasl>جَحِيمُ لِمَن <idgham>يَرَىٰ</idgham>", "Wa burrizatil-jahimu limay yara", "And Hellfire will be exposed for [all] those who see -", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.IDGHAM)),
            make(79, "An-Nazi'at", 37, "فَأَمَّا مَن طَغَىٰ", "فَ<ghunnah>أَمَّا</ghunnah> مَن <ikhfa>طَغَىٰ</ikhfa>", "Fa-amma man tagha", "So as for he who transgressed", listOf(TajweedRuleType.GHUNNAH)),
            make(79, "An-Nazi'at", 38, "وَآثَرَ الْحَيَاةَ الدُّنْيَا", "وَ<madd>آثَرَ</madd> <hamzat_wasl>الْ</hamzat_wasl>حَيَاةَ <hamzat_wasl>ال</hamzat_wasl>دُّنْيَا", "Wa atharal-hayatad-dunya", "And preferred the life of the world,", listOf(TajweedRuleType.MADD, TajweedRuleType.HAMZAT_WASL)),
            make(79, "An-Nazi'at", 39, "فَإِنَّ الْجَحِيمَ هِيَ الْمَأْوَىٰ", "فَ<ghunnah>إِنَّ</ghunnah> <hamzat_wasl>الْ</hamzat_wasl>جَحِيمَ هِيَ <hamzat_wasl>الْ</hamzat_wasl>مَأْوَىٰ", "Fa-innal-jahima hiyal-ma'wa", "Then indeed, Hellfire will be his refuge.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL)),
            make(79, "An-Nazi'at", 40, "وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِ وَنَهَى النَّفْسَ عَنِ الْهَوَىٰ", "وَ<ghunnah>أَمَّا</ghunnah> مَنْ خَافَ مَ<tafkhim>قَامَ</tafkhim> رَبِّهِ وَنَهَى <hamzat_wasl>ال</hamzat_wasl><ghunnah>نَّفْسَ</ghunnah> عَنِ <hamzat_wasl>الْ</hamzat_wasl>هَوَىٰ", "Wa amma man khafa maqama rabbihi wa nahan-nafsa 'anil-hawa", "But as for he who feared the position of his Lord and prevented the soul from [unlawful] inclination,", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL)),
            make(79, "An-Nazi'at", 41, "فَإِنَّ الْجَنَّةَ هِيَ الْمَأْوَىٰ", "فَ<ghunnah>إِنَّ</ghunnah> <hamzat_wasl>الْ</hamzat_wasl><ghunnah>جَنَّةَ</ghunnah> هِيَ <hamzat_wasl>الْ</hamzat_wasl>مَأْوَىٰ", "Fa-innal-jannata hiyal-ma'wa", "Then indeed, Paradise will be his refuge.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL)),
            make(79, "An-Nazi'at", 42, "يَسْأَلُونَكَ عَنِ السَّاعَةِ أَيَّانَ مُرْسَاهَا", "يَسْأَلُونَكَ عَنِ <hamzat_wasl>ال</hamzat_wasl>سَّاعَةِ أَيَّانَ مُرْسَاهَا", "Yas'alunaka 'anis-sa'ati ayyana mursaha", "They ask you, [O Muhammad], about the Hour: when is its arrival?", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(79, "An-Nazi'at", 43, "فِيمَ أَنتَ مِن ذِكْرَاهَا", "فِيمَ <ikhfa>أَنتَ</ikhfa> مِن <ikhfa>ذِكْرَاهَا</ikhfa>", "Fima anta min dhikraha", "In what [position] are you that you should mention it?", listOf(TajweedRuleType.GHUNNAH)),
            make(79, "An-Nazi'at", 44, "إِلَىٰ رَبِّكَ مُنتَهَاهَا", "إِلَىٰ رَبِّكَ مُن<ikhfa>تَهَاهَا</ikhfa>", "Ila rabbika muntahaha", "To your Lord is its finality.", listOf(TajweedRuleType.GHUNNAH)),
            make(79, "An-Nazi'at", 45, "إِنَّمَا أَنتَ مُنذِرُ مَن يَخْشَاهَا", "<ghunnah>إِنَّمَا</ghunnah> <madd>أَ</madd><ikhfa>نتَ</ikhfa> مُن<ikhfa>ذِرُ</ikhfa> مَن <idgham>يَخْشَاهَا</idgham>", "Innama anta mundhiru may yakhshaha", "You are only a warner for whoever would fear it.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.MADD, TajweedRuleType.IDGHAM)),
            make(79, "An-Nazi'at", 46, "كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوا إِلَّا عَشِيَّةً أَوْ ضُحَاهَا", "كَ<ghunnah>أَنَّهُمْ</ghunnah> يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوا إِلَّا عَشِيَّةً أَوْ <tafkhim>ضُحَاهَا</tafkhim>", "Ka-annahum yawma yarawnaha lam yalbathu illa 'ashiyyatan aw duhaha", "It will be, on the Day they see it, as though they had not remained [in the world] except for an afternoon or a morning thereof.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.TAFKHIM)),

            // ==================== SURAH 80: 'ABASA (42 Verses) ====================
            make(80, "'Abasa", 1, "عَبَسَ وَتَوَلَّىٰ", "عَبَسَ وَتَوَلَّىٰ", "'Abasa wa tawalla", "He [the Prophet] frowned and turned away", emptyList()),
            make(80, "'Abasa", 2, "أَن جَاءَهُ الْأَعْمَىٰ", "أَن <ikhfa>جَاءَهُ</ikhfa> <hamzat_wasl>الْ</hamzat_wasl>أَعْمَىٰ", "An ja'ahul-a'ma", "Because there came to him the blind man,", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.MADD, TajweedRuleType.HAMZAT_WASL)),
            make(80, "'Abasa", 3, "وَمَا يُدْرِيكَ لَعَلَّهُ يَزَّكَّىٰ", "وَمَا <qalqalah>يُدْرِيكَ</qalqalah> لَعَلَّهُ يَزَّكَّىٰ", "Wa ma yudrika la'allahu yazzakka", "But what would make you perceive, [O Muhammad], that perhaps he might be purified", listOf(TajweedRuleType.QALQALAH)),
            make(80, "'Abasa", 4, "أَوْ يَذَّكَّرُ فَتَنفَعَهُ الذِّكْرَىٰ", "أَوْ يَذَّكَّرُ فَتَن<ikhfa>فَعَهُ</ikhfa> <hamzat_wasl>ال</hamzat_wasl>ذِّكْرَىٰ", "Aw yadh-dhakkaru fa tanfa'ahudh-dhikra", "Or be reminded and the reminder would benefit him?", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL)),
            make(80, "'Abasa", 5, "أَمَّا مَنِ اسْتَغْنَىٰ", "<ghunnah>أَمَّا</ghunnah> مَنِ <hamzat_wasl>ا</hamzat_wasl>سْتَغْنَىٰ", "Amma manis-taghna", "As for he who thinks himself without need,", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL)),
            make(80, "'Abasa", 6, "فَأَنتَ لَهُ تَصَدَّىٰ", "فَ<ikhfa>أَنتَ</ikhfa> لَهُ <tafkhim>تَصَدَّىٰ</tafkhim>", "Fa-anta lahu tasadda", "To him you give attention.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.TAFKHIM)),
            make(80, "'Abasa", 7, "وَمَا عَلَيْكَ أَلَّا يَزَّكَّىٰ", "وَمَا عَلَيْكَ <idgham>أَلَّا</idgham> يَزَّكَّىٰ", "Wa ma 'alayka alla yazzakka", "And not upon you [is any blame] if he will not be purified.", listOf(TajweedRuleType.IDGHAM)),
            make(80, "'Abasa", 8, "وَأَمَّا مَن جَاءَكَ يَسْعَىٰ", "وَ<ghunnah>أَمَّا</ghunnah> مَن <ikhfa>جَاءَكَ</ikhfa> يَسْعَىٰ", "Wa amma man ja'aka yas'a", "But as for he who came to you striving [for knowledge]", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.MADD)),
            make(80, "'Abasa", 9, "وَهُوَ يَخْشَىٰ", "وَهُوَ يَخْشَىٰ", "Wa huwa yakhsha", "While he fears [Allah],", emptyList()),
            make(80, "'Abasa", 10, "فَأَنتَ عَنْهُ تَلَهَّىٰ", "فَ<ikhfa>أَنتَ</ikhfa> عَنْهُ تَلَهَّىٰ", "Fa-anta 'anhu talahha", "From him you are distracted.", listOf(TajweedRuleType.GHUNNAH)),
            make(80, "'Abasa", 11, "كَلَّا إِنَّهَا تَذْكِرَةٌ", "كَلَّا <madd>إِنَّهَا</madd> تَذْكِرَةٌ", "Kalla innaha tadhkirah", "No! Indeed, these verses are a reminder;", listOf(TajweedRuleType.MADD, TajweedRuleType.GHUNNAH)),
            make(80, "'Abasa", 12, "فَمَن شَاءَ ذَكَرَهُ", "فَمَن <ikhfa>شَاءَ</ikhfa> ذَكَرَهُ", "Faman sha'a dhakarah", "So whoever wills may remember it.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.MADD)),
            make(80, "'Abasa", 13, "فِي صُحُفٍ مُّكَرَّمَةٍ", "فِي <tafkhim>صُحُفٍ</tafkhim> <idgham>مُّكَرَّمَةٍ</idgham>", "Fi suhufim mukarramah", "[It is recorded] in honored sheets,", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.IDGHAM)),
            make(80, "'Abasa", 14, "مَّرْفُوعَةٍ مُّطَهَّرَةٍ", "مَّرْفُوعَةٍ <idgham>مُّطَهَّرَةٍ</idgham>", "Marfu'atim mutahharah", "Exalted and purified,", listOf(TajweedRuleType.IDGHAM)),
            make(80, "'Abasa", 15, "بِأَيْدِي سَفَرَةٍ", "بِأَيْدِي سَفَرَةٍ", "Bi-aydi safarah", "[Carried] by the hands of messenger-angels,", emptyList()),
            make(80, "'Abasa", 16, "كِرَامٍ بَرَرَةٍ", "كِرَامٍ <iqlab>بَرَرَةٍ</iqlab>", "Kiramim bararah", "Noble and dutiful.", listOf(TajweedRuleType.IQLAB)),
            make(80, "'Abasa", 17, "قُتِلَ الْإِنسَانُ مَا أَكْفَرَهُ", "<tafkhim>قُتِلَ</tafkhim> <hamzat_wasl>الْ</hamzat_wasl>إِ<ikhfa>نسَانُ</ikhfa> <madd>مَا</madd> أَكْفَرَهُ", "Qutilal-insanu ma akfarah", "Cursed is man; how disbelieving is he.", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH, TajweedRuleType.MADD)),
            make(80, "'Abasa", 18, "مِنْ أَيِّ شَيْءٍ خَلَقَهُ", "مِنْ أَيِّ شَيْءٍ خَلَ<qalqalah>قَهُ</qalqalah>", "Min ayyi shay'in khalaqah", "From what substance did He create him?", listOf(TajweedRuleType.QALQALAH)),
            make(80, "'Abasa", 19, "مِن نُّطْفَةٍ خَلَقَهُ فَقَدَّرَهُ", "مِن <idgham>نُّ</idgham><tafkhim>طْفَةٍ</tafkhim> خَلَ<qalqalah>قَهُ</qalqalah> فَ<tafkhim>قَدَّرَهُ</tafkhim>", "Min nutfatin khalaqahu faqaddarah", "From a sperm-drop He created him and destined for him;", listOf(TajweedRuleType.IDGHAM, TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),
            make(80, "'Abasa", 20, "ثُمَّ السَّبِيلَ يَسَّرَهُ", "<ghunnah>ثُمَّ</ghunnah> <hamzat_wasl>ال</hamzat_wasl>سَّبِيلَ يَسَّرَهُ", "Thummas-sabila yassarah", "Then He eased the way for him;", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL)),
            make(80, "'Abasa", 21, "ثُمَّ أَمَاتَهُ فَأَقْبَرَهُ", "<ghunnah>ثُمَّ</ghunnah> <madd>أَمَاتَهُ</madd> فَ<qalqalah>أَ</qalqalah><tafkhim>قْ</tafkhim><qalqalah>بَرَهُ</qalqalah>", "Thumma amatahu fa-aqbarah", "Then He causes his death and provides a grave for him.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.MADD, TajweedRuleType.QALQALAH, TajweedRuleType.TAFKHIM)),
            make(80, "'Abasa", 22, "ثُمَّ إِذَا شَاءَ أَنشَرَهُ", "<ghunnah>ثُمَّ</ghunnah> إِذَا <madd>شَاءَ</madd> <madd>أَن</madd><ikhfa>شَرَهُ</ikhfa>", "Thumma idha sha'a ansharah", "Then when He wills, He will resurrect him.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.MADD)),
            make(80, "'Abasa", 23, "كَلَّا لَمَّا يَقْضِ مَا أَمَرَهُ", "كَلَّا <ghunnah>لَمَّا</ghunnah> <qalqalah>يَ</qalqalah><tafkhim>قْضِ</tafkhim> <madd>مَا</madd> أَمَرَهُ", "Kalla lamma yaqdi ma amarah", "No! Man has not yet accomplished what He commanded him.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.QALQALAH, TajweedRuleType.TAFKHIM, TajweedRuleType.MADD)),
            make(80, "'Abasa", 24, "فَلْيَنظُرِ الْإِنسَانُ إِلَىٰ طَعَامِهِ", "فَلْيَن<ikhfa>ظُرِ</ikhfa> <hamzat_wasl>الْ</hamzat_wasl>إِ<ikhfa>نسَانُ</ikhfa> إِلَىٰ <tafkhim>طَعَامِهِ</tafkhim>", "Falyanzuril-insanu ila ta'amih", "Then let mankind look at his food -", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(80, "'Abasa", 25, "أَنَّا صَبَبْنَا الْمَاءَ صَبًّا", "<ghunnah>أَنَّا</ghunnah> <tafkhim>صَبَ</tafkhim><qalqalah>بْ</qalqalah>نَا <hamzat_wasl>الْ</hamzat_wasl><madd>مَاءَ</madd> <tafkhim>صَبًّ</tafkhim><qalqalah>ا</qalqalah>", "Anna sababnal-ma'a sabba", "How We poured down water in torrents,", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD)),
            make(80, "'Abasa", 26, "ثُمَّ شَقَقْنَا الْأَرْضَ شَقًّا", "<ghunnah>ثُمَّ</ghunnah> شَ<qalqalah>قَ</qalqalah><qalqalah>قْ</qalqalah>نَا <hamzat_wasl>الْ</hamzat_wasl>أَرْضَ شَ<qalqalah>قًّ</qalqalah>ا", "Thumma shaqaqnal-arda shaqqa", "Then We broke open the earth, splitting [it with sprouts],", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.QALQALAH, TajweedRuleType.HAMZAT_WASL)),
            make(80, "'Abasa", 27, "فَأَنبَتْنَا فِيهَا حَبًّ۠ا", "فَ<iqlab>أَنبَتْنَا</iqlab> فِيهَا حَبًّا", "Fa-anbatna fiha habba", "And caused to grow within it grain", listOf(TajweedRuleType.IQLAB)),
            make(80, "'Abasa", 28, "وَعِنَبًا وَقَضْبًا", "وَعِنَبًا <idgham>وَ</idgham><tafkhim>قَ</tafkhim><tafkhim>ضْ</tafkhim><qalqalah>بً</qalqalah>ا", "Wa 'inabaw wa qadba", "And grapes and herbage", listOf(TajweedRuleType.IDGHAM, TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),
            make(80, "'Abasa", 29, "وَزَيْتُونًا وَنَخْلًا", "وَزَيْتُونًا <idgham>وَنَخْلًا</idgham>", "Wa zaytunaw wa nakhla", "And olive and palm trees", listOf(TajweedRuleType.IDGHAM)),
            make(80, "'Abasa", 30, "وَحَدَائِقَ غُلْبًا", "وَحَ<madd>دَائِقَ</madd> غُلْبًا", "Wa hada'iqa ghulba", "And gardens of dense shrubbery", listOf(TajweedRuleType.MADD)),
            make(80, "'Abasa", 31, "وَفَاكِهَةً وَأَبًّا", "وَفَاكِهَةً <idgham>وَأَبًّا</idgham>", "Wa fakihataw wa abba", "And fruit and grass -", listOf(TajweedRuleType.IDGHAM)),
            make(80, "'Abasa", 32, "مَّتَاعًا لَّكُمْ وَلِأَنْعَامِكُمْ", "مَّتَاعًا <idgham>لَّكُمْ</idgham> وَلِأَنْعَامِكُمْ", "Mata'al lakum wa li-an'amikum", "[As] enjoyment and provision for you and your grazing livestock.", listOf(TajweedRuleType.IDGHAM)),
            make(80, "'Abasa", 33, "فَإِذَا جَاءَتِ الصَّاخَّةُ", "فَإِذَا <madd>جَاءَتِ</madd> <hamzat_wasl>ال</hamzat_wasl><madd>صَّاخَّةُ</madd>", "Fa-idha ja'atis-sakhkhah", "But when there comes the Deafening Blast", listOf(TajweedRuleType.MADD, TajweedRuleType.HAMZAT_WASL)),
            make(80, "'Abasa", 34, "يَوْمَ يَفِرُّ الْمَرْءُ مِنْ أَخِيهِ", "يَوْمَ يَفِرُّ <hamzat_wasl>الْ</hamzat_wasl>مَرْءُ مِنْ أَخِيهِ", "Yawma yafirrul-mar'u min akhih", "On the Day a man will flee from his brother", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(80, "'Abasa", 35, "وَأُمِّهِ وَأَبِيهِ", "وَ<ghunnah>أُمِّهِ</ghunnah> وَأَبِيهِ", "Wa ummihi wa abih", "And his mother and his father", listOf(TajweedRuleType.GHUNNAH)),
            make(80, "'Abasa", 36, "وَصَاحِبَتِهِ وَبَنِيهِ", "وَ<tafkhim>صَاحِبَتِهِ</tafkhim> وَبَنِيهِ", "Wa sahibatihi wa banih", "And his wife and his children,", listOf(TajweedRuleType.TAFKHIM)),
            make(80, "'Abasa", 37, "لِكُلِّ امْرِئٍ مِّنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ", "لِكُلِّ <hamzat_wasl>ا</hamzat_wasl>مْرِئٍ <idgham>مِّنْهُمْ</idgham> يَوْمَئِذٍ <ikhfa>شَأْنٌ</ikhfa> <idgham>يُغْنِيهِ</idgham>", "Likullim-ri'im minhum yawma'idhin sha'nuy yughnih", "For every man, that Day, will be a matter adequate for him.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.IDGHAM, TajweedRuleType.GHUNNAH)),
            make(80, "'Abasa", 38, "وُجُوهٌ يَوْمَئِذٍ مُّسْفِرَةٌ", "وُجُوهٌ <idgham>يَوْمَئِذٍ</idgham> <idgham>مُّسْفِرَةٌ</idgham>", "Wujuhuy yawma'idhim musfirah", "[Some] faces, that Day, will be bright -", listOf(TajweedRuleType.IDGHAM)),
            make(80, "'Abasa", 39, "ضَاحِكَةٌ مُّسْتَبْشِرَةٌ", "<tafkhim>ضَاحِكَةٌ</tafkhim> <idgham>مُّسْتَبْشِرَةٌ</idgham>", "Dahikatum mustabshirah", "Laughing, rejoicing at good news.", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.IDGHAM)),
            make(80, "'Abasa", 40, "وَوُجُوهٌ يَوْمَئِذٍ عَلَيْهَا غَبَرَةٌ", "وَوُجُوهٌ <idgham>يَوْمَئِذٍ</idgham> عَلَيْهَا غَبَرَةٌ", "Wa wujuhuy yawma'idhin 'alayha ghabarah", "And [other] faces, that Day, will have upon them dust.", listOf(TajweedRuleType.IDGHAM)),
            make(80, "'Abasa", 41, "تَرْهَقُهَا قَتَرَةٌ", "تَرْهَ<tafkhim>قُهَا</tafkhim> <tafkhim>قَتَرَةٌ</tafkhim>", "Tarhaquha qatarah", "Blackness will cover them.", listOf(TajweedRuleType.TAFKHIM)),
            make(80, "'Abasa", 42, "أُولَٰئِكَ هُمُ الْكَفَرَةُ الْفَجَرَةُ", "أُو<madd>لَٰئِكَ</madd> هُمُ <hamzat_wasl>الْ</hamzat_wasl>كَفَرَةُ <hamzat_wasl>الْ</hamzat_wasl>فَجَرَةُ", "Ula'ika humul-kafaratul-fajarah", "Those are the disbelievers, the wicked ones.", listOf(TajweedRuleType.MADD, TajweedRuleType.HAMZAT_WASL)),

            // ==================== SURAH 81: AT-TAKWIR (29 Verses) ====================
            make(81, "At-Takwir", 1, "إِذَا الشَّمْسُ كُوِّرَتْ", "إِذَا <hamzat_wasl>ال</hamzat_wasl>شَّمْسُ كُوِّرَتْ", "Idhash-shamsu kuwwirat", "When the sun is wrapped up [in darkness]", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(81, "At-Takwir", 2, "وَإِذَا النُّجُومُ انكَدَرَتْ", "وَإِذَا <hamzat_wasl>ال</hamzat_wasl><ghunnah>نُّجُومُ</ghunnah> ان<ikhfa>كَدَرَتْ</ikhfa>", "Wa idhan-nujumun-kadarat", "And when the stars fall, dispersing,", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH)),
            make(81, "At-Takwir", 3, "وَإِذَا الْجِبَالُ سُيِّرَتْ", "وَإِذَا <hamzat_wasl>الْ</hamzat_wasl>جِبَالُ سُيِّرَتْ", "Wa idhal-jibalu suyyirat", "And when the mountains are removed", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(81, "At-Takwir", 4, "وَإِذَا الْعِشَارُ عُطِّلَتْ", "وَإِذَا <hamzat_wasl>الْ</hamzat_wasl>عِشَارُ عُطِّلَتْ", "Wa idhal-'isharu 'uttilat", "And when full-term she-camels are neglected", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(81, "At-Takwir", 5, "وَإِذَا الْوُحُوشُ حُشِرَتْ", "وَإِذَا <hamzat_wasl>الْ</hamzat_wasl>وُحُوشُ حُشِرَتْ", "Wa idhal-wuhushu hushirat", "And when the wild beasts are gathered", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(81, "At-Takwir", 6, "وَإِذَا الْبِحَارُ سُجِّرَتْ", "وَإِذَا <hamzat_wasl>الْ</hamzat_wasl>بِحَارُ سُجِّرَتْ", "Wa idhal-biharu sujjirat", "And when the seas are set on fire", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(81, "At-Takwir", 7, "وَإِذَا النُّفُوسُ زُوِّجَتْ", "وَإِذَا <hamzat_wasl>ال</hamzat_wasl><ghunnah>نُّفُوسُ</ghunnah> زُوِّجَتْ", "Wa idhan-nufusu zuwwijat", "And when the souls are paired", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH)),
            make(81, "At-Takwir", 8, "وَإِذَا الْمَوْءُودَةُ سُئِلَتْ", "وَإِذَا <hamzat_wasl>الْ</hamzat_wasl>مَوْءُودَةُ سُئِلَتْ", "Wa idhal-maw'udatu su'ilat", "And when the girl [who was] buried alive is asked", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(81, "At-Takwir", 9, "بِأَيِّ ذَنبٍ قُتِلَتْ", "بِأَيِّ <iqlab>ذَنبٍ</iqlab> <tafkhim>قُتِلَتْ</tafkhim>", "Bi-ayyi dhambin qutilat", "For what sin she was killed", listOf(TajweedRuleType.IQLAB, TajweedRuleType.TAFKHIM)),
            make(81, "At-Takwir", 10, "وَإِذَا الصُّحُفُ نُشِرَتْ", "وَإِذَا <hamzat_wasl>ال</hamzat_wasl><tafkhim>صُّحُفُ</tafkhim> نُشِرَتْ", "Wa idhas-suhufu nushirat", "And when the pages are made public", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(81, "At-Takwir", 11, "وَإِذَا السَّمَاءُ كُشِطَتْ", "وَإِذَا <hamzat_wasl>ال</hamzat_wasl><madd>سَّمَاءُ</madd> كُشِطَتْ", "Wa idhas-sama'u kushitat", "And when the sky is stripped away", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD)),
            make(81, "At-Takwir", 12, "وَإِذَا الْجَحِيمُ سُعِّرَتْ", "وَإِذَا <hamzat_wasl>الْ</hamzat_wasl>جَحِيمُ سُعِّرَتْ", "Wa idhal-jahimu su''irat", "And when Hellfire is set ablaze", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(81, "At-Takwir", 13, "وَإِذَا الْجَنَّةُ أُزْلِفَتْ", "وَإِذَا <hamzat_wasl>الْ</hamzat_wasl><ghunnah>جَنَّةُ</ghunnah> أُزْلِفَتْ", "Wa idhal-jannatu uzlifat", "And when Paradise is brought near,", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH)),
            make(81, "At-Takwir", 14, "عَلِمَتْ نَفْسٌ مَّا أَحْضَرَتْ", "عَلِمَتْ نَفْسٌ <idgham>مَّا</idgham> <madd>أَحْضَرَتْ</madd>", "'Alimat nafsum ma ahdarat", "A soul will [then] know what it has brought [with it].", listOf(TajweedRuleType.IDGHAM, TajweedRuleType.MADD)),
            make(81, "At-Takwir", 15, "فَلَا أُقْسِمُ بِالْخُنَّسِ", "فَلَا <madd>أُ</madd><qalqalah>قْسِمُ</qalqalah> بِ<hamzat_wasl>الْ</hamzat_wasl>خُ<ghunnah>نَّسِ</ghunnah>", "Fala uqsimu bil-khunnas", "So I swear by the retreating stars -", listOf(TajweedRuleType.MADD, TajweedRuleType.QALQALAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH)),
            make(81, "At-Takwir", 16, "الْجَوَارِ الْكُنَّسِ", "<hamzat_wasl>الْ</hamzat_wasl>جَوَارِ <hamzat_wasl>الْ</hamzat_wasl>كُ<ghunnah>نَّسِ</ghunnah>", "Al-jawaril-kunnas", "Those that run [their courses] and disappear -", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH)),
            make(81, "At-Takwir", 17, "وَاللَّيْلِ إِذَا عَسْعَسَ", "وَ<hamzat_wasl>ال</hamzat_wasl>لَّيْلِ إِذَا عَسْعَسَ", "Wal-layli idha 'as'as", "And by the night as it closes in", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(81, "At-Takwir", 18, "وَالصُّبْحِ إِذَا تَنَفَّسَ", "وَ<hamzat_wasl>ال</hamzat_wasl><tafkhim>صُّ</tafkhim><qalqalah>بْ</qalqalah>حِ إِذَا تَنَفَّسَ", "Was-subhi idha tanaffas", "And by the dawn when it breathes [with light],", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),
            make(81, "At-Takwir", 19, "إِنَّهُ لَقَوْلُ رَسُولٍ كَرِيمٍ", "<ghunnah>إِنَّهُ</ghunnah> لَ<tafkhim>قَوْلُ</tafkhim> رَسُولٍ <ikhfa>كَرِيمٍ</ikhfa>", "Innahu laqawlu rasulin karim", "[That] indeed, the Qur'an is a word [conveyed by] a noble messenger", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.TAFKHIM)),
            make(81, "At-Takwir", 20, "ذِي قُوَّةٍ عِندَ ذِي الْعَرْشِ مَكِينٍ", "ذِي <tafkhim>قُوَّةٍ</tafkhim> عِن<ikhfa>دَ</ikhfa> ذِي <hamzat_wasl>الْ</hamzat_wasl>عَرْشِ مَكِينٍ", "Dhi quwwatin 'inda dhil-'arshi makin", "[Who is] possessed of power and with the Owner of the Throne, secure [in position],", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL)),
            make(81, "At-Takwir", 21, "مُّطَاعٍ ثَمَّ أَمِينٍ", "مُّ<tafkhim>طَاعٍ</tafkhim> <ikhfa>ثَمَّ</ikhfa> أَمِينٍ", "Muta'in thamma amin", "Obeyed there [in the heavens] and trustworthy.", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.GHUNNAH)),
            make(81, "At-Takwir", 22, "وَمَا صَاحِبُكُم بِمَجْنُونٍ", "وَمَا <tafkhim>صَاحِبُكُم</tafkhim> <ikhfa>بِمَ</ikhfa><qalqalah>جْ</qalqalah>نُونٍ", "Wa ma sahibukum bimajnun", "And your companion is not [at all] mad.", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.GHUNNAH, TajweedRuleType.QALQALAH)),
            make(81, "At-Takwir", 23, "وَلَقَدْ رَآهُ بِالْأُفُقِ الْمُبِينِ", "وَلَ<qalqalah>قَدْ</qalqalah> <madd>رَآهُ</madd> بِ<hamzat_wasl>الْ</hamzat_wasl>أُ<tafkhim>فُقِ</tafkhim> <hamzat_wasl>الْ</hamzat_wasl>مُبِينِ", "Wa laqad ra'ahu bil-ufuqil-mubin", "And he has already seen Gabriel in the clear horizon.", listOf(TajweedRuleType.QALQALAH, TajweedRuleType.MADD, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(81, "At-Takwir", 24, "وَمَا هُوَ عَلَى الْغَيْبِ بِضَنِينٍ", "وَمَا هُوَ عَلَى <hamzat_wasl>الْ</hamzat_wasl>غَيْبِ بِ<tafkhim>ضَنِينٍ</tafkhim>", "Wa ma huwa 'alal-ghaybi bidanin", "And Muhammad is not a withholder of [knowledge of] the unseen.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(81, "At-Takwir", 25, "وَمَا هُوَ بِقَوْلِ شَيْطَانٍ رَّجِيمٍ", "وَمَا هُوَ بِ<tafkhim>قَوْلِ</tafkhim> شَيْ<tafkhim>طَانٍ</tafkhim> <idgham>رَّجِيمٍ</idgham>", "Wa ma huwa biqawli shaytanir rajim", "And the Qur'an is not the word of a devil, expelled [from the heavens].", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.IDGHAM)),
            make(81, "At-Takwir", 26, "فَأَيْنَ تَذْهَبُونَ", "فَأَيْنَ تَذْهَبُونَ", "Fa-ayna tadh-habun", "So where are you going?", emptyList()),
            make(81, "At-Takwir", 27, "إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَالَمِينَ", "إِنْ هُوَ إِلَّا ذِكْرٌ <idgham>لِّلْعَالَمِينَ</idgham>", "In huwa illa dhikrul lil-'alamin", "It is not except a reminder to the worlds", listOf(TajweedRuleType.IDGHAM)),
            make(81, "At-Takwir", 28, "لِمَن شَاءَ مِنكُمْ أَن يَسْتَقِيمَ", "لِمَن <ikhfa>شَاءَ</ikhfa> مِن<ikhfa>كُم</ikhfa> أَن <idgham>يَسْتَقِيمَ</idgham>", "Liman sha'a minkum ay yastaqim", "For whoever wills among you to take a right course.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.MADD, TajweedRuleType.IDGHAM)),
            make(81, "At-Takwir", 29, "وَمَا تَشَاءُونَ إِلَّا أَن يَشَاءَ اللَّهُ رَبُّ الْعَالَمِينَ", "وَمَا <madd>تَشَاءُونَ</madd> إِلَّا <madd>أَن</madd> <idgham>يَشَاءَ</idgham> <hamzat_wasl>ال</hamzat_wasl><tafkhim>لَّهُ</tafkhim> رَبُّ <hamzat_wasl>الْ</hamzat_wasl>عَالَمِينَ", "Wa ma tasha'una illa ay yasha'al-lahu rabbul-'alamin", "And you do not will except that Allah wills - Lord of the worlds.", listOf(TajweedRuleType.MADD, TajweedRuleType.IDGHAM, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),

            // ==================== SURAH 82: AL-INFITAR (19 Verses) ====================
            make(82, "Al-Infitar", 1, "إِذَا السَّمَاءُ انفَطَرَتْ", "إِذَا <hamzat_wasl>ال</hamzat_wasl><madd>سَّمَاءُ</madd> ان<ikhfa>فَطَرَتْ</ikhfa>", "Idhas-sama'un-fatarat", "When the sky breaks apart", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD, TajweedRuleType.GHUNNAH)),
            make(82, "Al-Infitar", 2, "وَإِذَا الْكَوَاكِبُ انتَثَرَتْ", "وَإِذَا <hamzat_wasl>الْ</hamzat_wasl>كَوَاكِبُ ان<ikhfa>تَثَرَتْ</ikhfa>", "Wa idhal-kawakibun-tatharat", "And when the stars fall, scattering,", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH)),
            make(82, "Al-Infitar", 3, "وَإِذَا الْبِحَارُ فُجِّرَتْ", "وَإِذَا <hamzat_wasl>الْ</hamzat_wasl>بِحَارُ فُجِّرَتْ", "Wa idhal-biharu fujjirat", "And when the seas are erupted", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(82, "Al-Infitar", 4, "وَإِذَا الْقُبُورُ بُعْثِرَتْ", "وَإِذَا <hamzat_wasl>الْ</hamzat_wasl><tafkhim>قُبُورُ</tafkhim> بُعْثِرَتْ", "Wa idhal-quburu bu'thirat", "And when the contents of graves are scattered,", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(82, "Al-Infitar", 5, "عَلِمَتْ نَفْسٌ مَّا قَدَّمَتْ وَأَخَّرَتْ", "عَلِمَتْ نَفْسٌ <idgham>مَّا</idgham> <tafkhim>قَدَّمَتْ</tafkhim> وَأَخَّرَتْ", "'Alimat nafsum ma qaddamat wa akh-kharat", "A soul will [then] know what it has put forth and kept back.", listOf(TajweedRuleType.IDGHAM, TajweedRuleType.TAFKHIM)),
            make(82, "Al-Infitar", 6, "يَا أَيُّهَا الْإِنسَانُ مَا غَرَّكَ بِرَبِّكَ الْكَرِيمِ", "يَا <madd>أَيُّهَا</madd> <hamzat_wasl>الْ</hamzat_wasl>إِ<ikhfa>نسَانُ</ikhfa> مَا غَرَّكَ بِرَبِّكَ <hamzat_wasl>الْ</hamzat_wasl>كَرِيمِ", "Ya ayyuhal-insanu ma gharraka birabbikal-karim", "O mankind, what has deceived you concerning your Lord, the Generous,", listOf(TajweedRuleType.MADD, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH)),
            make(82, "Al-Infitar", 7, "الَّذِي خَلَقَكَ فَسَوَّاكَ فَعَدَلَكَ", "<hamzat_wasl>الَّذِي</hamzat_wasl> خَلَ<tafkhim>قَكَ</tafkhim> فَسَوَّاكَ فَعَدَلَكَ", "Alladhi khalaqaka fasawwaka fa'adalak", "Who created you, proportioned you, and balanced you?", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(82, "Al-Infitar", 8, "فِي أَيِّ صُورَةٍ مَّا شَاءَ رَكَّبَكَ", "فِي <madd>أَيِّ</madd> <tafkhim>صُورَةٍ</tafkhim> <idgham>مَّا</idgham> <madd>شَاءَ</madd> رَكَّبَكَ", "Fi ayyi suratim ma sha'a rakkabak", "In whatever form He willed has He assembled you.", listOf(TajweedRuleType.MADD, TajweedRuleType.TAFKHIM, TajweedRuleType.IDGHAM)),
            make(82, "Al-Infitar", 9, "كَلَّا بَلْ تُكَذِّبُونَ بِالدِّينِ", "كَلَّا بَلْ تُكَذِّبُونَ بِ<hamzat_wasl>ال</hamzat_wasl>دِّينِ", "Kalla bal tukadh-dhibuna bid-din", "No! But you deny the Recompense.", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(82, "Al-Infitar", 10, "وَإِنَّ عَلَيْكُمْ لَحَافِظِينَ", "وَ<ghunnah>إِنَّ</ghunnah> عَلَيْكُمْ لَحَافِظِينَ", "Wa inna 'alaykum lahafizin", "And indeed, [appointed] over you are keepers,", listOf(TajweedRuleType.GHUNNAH)),
            make(82, "Al-Infitar", 11, "كِرَامًا كَاتِبِينَ", "كِرَامًا <ikhfa>كَاتِبِينَ</ikhfa>", "Kiramang katibin", "Noble and recording;", listOf(TajweedRuleType.GHUNNAH)),
            make(82, "Al-Infitar", 12, "يَعْلَمُونَ مَا تَفْعَلُونَ", "يَعْلَمُونَ مَا تَفْعَلُونَ", "Ya'lamuna ma taf'alun", "They know whatever you do.", emptyList()),
            make(82, "Al-Infitar", 13, "إِنَّ الْأَبْرَارَ لَفِي نَعِيمٍ", "<ghunnah>إِنَّ</ghunnah> <hamzat_wasl>الْ</hamzat_wasl>أَ<qalqalah>بْ</qalqalah>رَارَ لَفِي نَعِيمٍ", "Innal-abrara lafi na'im", "Indeed, the righteous will be in pleasure,", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.QALQALAH)),
            make(82, "Al-Infitar", 14, "وَإِنَّ الْفُجَّارَ لَفِي جَحِيمٍ", "وَ<ghunnah>إِنَّ</ghunnah> <hamzat_wasl>الْ</hamzat_wasl>فُجَّارَ لَفِي جَحِيمٍ", "Wa innal-fujjara lafi jahim", "And indeed, the wicked will be in Hellfire.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL)),
            make(82, "Al-Infitar", 15, "يَصْلَوْنَهَا يَوْمَ الدِّينِ", "<tafkhim>يَصْلَوْنَهَا</tafkhim> يَوْمَ <hamzat_wasl>ال</hamzat_wasl>دِّينِ", "Yaslawnaha yawmad-din", "They will [enter to] burn therein on the Day of Recompense,", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.HAMZAT_WASL)),
            make(82, "Al-Infitar", 16, "وَمَا هُمْ عَنْهَا بِغَائِبِينَ", "وَمَا هُمْ عَنْهَا بِ<madd>غَائِبِينَ</madd>", "Wa ma hum 'anha bigha'ibin", "And never will they be absent therefrom.", listOf(TajweedRuleType.MADD)),
            make(82, "Al-Infitar", 17, "وَمَا أَدْرَاكَ مَا يَوْمُ الدِّينِ", "وَمَا <madd>أَ</madd><qalqalah>دْرَاكَ</qalqalah> مَا يَوْمُ <hamzat_wasl>ال</hamzat_wasl>دِّينِ", "Wa ma adraka ma yawmud-din", "And what can make you know what is the Day of Recompense?", listOf(TajweedRuleType.MADD, TajweedRuleType.QALQALAH, TajweedRuleType.HAMZAT_WASL)),
            make(82, "Al-Infitar", 18, "ثُمَّ مَا أَدْرَاكَ مَا يَوْمُ الدِّينِ", "<ghunnah>ثُمَّ</ghunnah> <madd>مَا</madd> <qalqalah>أَدْرَاكَ</qalqalah> مَا يَوْمُ <hamzat_wasl>ال</hamzat_wasl>دِّينِ", "Thumma ma adraka ma yawmud-din", "Then, what can make you know what is the Day of Recompense?", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.MADD, TajweedRuleType.QALQALAH, TajweedRuleType.HAMZAT_WASL)),
            make(82, "Al-Infitar", 19, "يَوْمَ لَا تَمْلِكُ نَفْسٌ لِّنَفْسٍ شَيْئًا ۖ وَالْأَمْرُ يَوْمَئِذٍ لِّلَّهِ", "يَوْمَ لَا تَمْلِكُ نَفْسٌ <idgham>لِّنَفْسٍ</idgham> <ikhfa>شَيْئًا</ikhfa> ۖ وَ<hamzat_wasl>الْ</hamzat_wasl>أَمْرُ يَوْمَئِذٍ <idgham>لِّلَّهِ</idgham>", "Yawma la tamliku nafsul linafsin shay'aw wal-amru yawma'idhil lil-lah", "It is the Day when a soul will not possess for another soul [power to do] a thing; and the command, that Day, is [entirely] with Allah.", listOf(TajweedRuleType.IDGHAM, TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL))
        )
    }
}
